    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { qty: 100, unitPrice: 100, discountPercent: 95 },
      { qty: 10, unitPrice: 10 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Subtotal: 10000 + 100 = 10100
  // Line 1 discount: 10000 * 95% = 9500
