  assert.equal(r.value.lines[0].qty, 2);
  assert.equal(r.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].qty, 1);
});

test('removeLine reports NOT_DRAFT if invoice is not draft', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  invoice.status = 'sent';

  const r = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine reports NOT_DRAFT for null invoice', () => {
  const r = removeLine(null, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine reports LINE_NOT_FOUND if SKU not on invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
